import Foundation
import GenmaiBase
import Testing
@testable import GenmaiCore

/// aux_dictionary.txt and dictionary.txt are generated by Bazel
/// (//data/dictionary_oss:aux_dictionary / :dictionary). Use them from
/// bazel-bin when the oracle has been built; otherwise the checked-in
/// dictionary00-09.txt that dictionary.txt is made of (aux_dictionary.txt,
/// generated from aux_dictionary.tsv, is then skipped).
private func ossDictionaryFiles(_ dictionaryDir: String) -> [String] {
  let generated = DataManagerTestSupport.sourcePath("bazel-bin", "data", "dictionary_oss")
  let aux = FileUtil.joinPath(generated, "aux_dictionary.txt")
  let dictionary = FileUtil.joinPath(generated, "dictionary.txt")
  if FileManager.default.fileExists(atPath: aux) && FileManager.default.fileExists(atPath: dictionary) {
    return [aux, dictionary]
  }
  return (0..<10).map { FileUtil.joinPath(dictionaryDir, "dictionary0\($0).txt") }
}

@Suite(.enabled(if: DataManagerTestSupport.hasOssData, "Data/genmai.data is missing; run Tools/build_oracle.sh to create it"))
struct OssDataManagerTest {
  @Test func allTests() throws {
    // kLSize / kRSize / IsBoundaryInternal of the generated segmenter_inl.inc.
    let segmenterInternal = try SegmenterInternal(
      idFile: DataManagerTestSupport.sourcePath("data", "dictionary_oss", "id.def"),
      specialPosFile: DataManagerTestSupport.sourcePath("data", "rules", "special_pos.def"),
      segmenterDef: DataManagerTestSupport.sourcePath("data", "rules", "segmenter.def"))
    let dictionaryDir = DataManagerTestSupport.sourcePath("data", "dictionary_oss")
    let base = DataManagerTestBase(
      dataManager: try OssDataManager(),
      lsize: segmenterInternal.lsize, rsize: segmenterInternal.rsize,
      isBoundary: segmenterInternal.isBoundaryInternal,
      connectionTxtFile: FileUtil.joinPath(dictionaryDir, "connection_single_column.txt"),
      expectedResolution: 1,
      dictionaryFiles: ossDictionaryFiles(dictionaryDir),
      suggestionFilterFiles: [FileUtil.joinPath(dictionaryDir, "suggestion_filter.txt")])
    // The rule table has the size of the segmenter data and is not trivial.
    #expect(segmenterInternal.lsize <= base.dataManager.getSegmenterData().lTable.count)
    #expect(segmenterInternal.rsize <= base.dataManager.getSegmenterData().rTable.count)
    #expect(
      (1..<segmenterInternal.lsize).contains { rid in
        (1..<segmenterInternal.rsize).contains { !segmenterInternal.isBoundaryInternal(rid, $0) }
      })
    try base.runAllTests()
  }

  // Swift-only: the default data path and the OSS magic number.
  @Test func defaultDataPathAndMagic() throws {
    let dm = try OssDataManager()
    #expect(dm.getFilename() == OssDataManager.defaultDataPath)
    let mmap = try Mmap.map(OssDataManager.defaultDataPath)
    let magic = DataManager.getDataSetMagicNumber("oss")
    #expect(magic.count == OssDataManager.kMagicNumberLength)
    #expect(Array(mmap.buffer.prefix(magic.count)) == magic)
    #expect(dm.getDataVersion().hasSuffix(".oss"))
  }

  @Test func missingFileThrows() {
    #expect(throws: StatusError.self) {
      _ = try OssDataManager(path: "/nonexistent/genmai.data")
    }
  }
}
